ALTER TABLE public.staff_assignments ADD COLUMN country text;
UPDATE public.staff_assignments SET country=public.account_country(user_id) WHERE responsibility='disputes';
COMMENT ON COLUMN public.staff_assignments.country IS 'Manager-selected registration-country scope for dispute supervision; NULL grants no delegated dispute access.';
CREATE OR REPLACE FUNCTION public.can_supervise_dispute(_user_id uuid,_order_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') OR EXISTS(SELECT 1 FROM public.staff_assignments s JOIN public.orders o ON o.id=_order_id WHERE s.user_id=_user_id AND s.responsibility='disputes' AND s.country IS NOT NULL AND s.country=public.account_country(o.seller_id)); $$;
REVOKE ALL ON FUNCTION public.can_supervise_dispute(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_supervise_dispute(uuid,uuid) TO authenticated;
CREATE FUNCTION public.assign_dispute_supervisor(_user_id uuid,_country text,_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id) THEN RAISE EXCEPTION 'INVALID_STAFF'; END IF;
IF _enabled THEN
IF _country IS NULL OR NOT (_country=ANY(ARRAY['ليبيا','السعودية','الإمارات','مصر','تونس','الجزائر','المغرب','الأردن','العراق','الكويت','قطر','البحرين','عُمان','اليمن','سوريا','لبنان','فلسطين','السودان','موريتانيا','تركيا','ألمانيا','فرنسا','بريطانيا','الولايات المتحدة','أخرى'])) THEN RAISE EXCEPTION 'COUNTRY_REQUIRED'; END IF;
INSERT INTO public.staff_assignments(user_id,responsibility,assigned_by,country) VALUES(_user_id,'disputes',auth.uid(),_country) ON CONFLICT(user_id,responsibility) DO UPDATE SET country=EXCLUDED.country,assigned_by=EXCLUDED.assigned_by;
ELSE DELETE FROM public.staff_assignments WHERE user_id=_user_id AND responsibility='disputes'; END IF; END $$;
REVOKE ALL ON FUNCTION public.assign_dispute_supervisor(uuid,text,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.assign_dispute_supervisor(uuid,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.assign_staff(_user_id uuid,_responsibility text,_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF _responsibility NOT IN ('forum','disputes') OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id) THEN RAISE EXCEPTION 'INVALID_STAFF'; END IF; IF _enabled THEN IF _responsibility='disputes' AND NOT EXISTS(SELECT 1 FROM public.staff_assignments WHERE user_id=_user_id AND responsibility='disputes' AND country IS NOT NULL) THEN RAISE EXCEPTION 'COUNTRY_REQUIRED'; END IF; INSERT INTO public.staff_assignments(user_id,responsibility,assigned_by) VALUES(_user_id,_responsibility,auth.uid()) ON CONFLICT DO NOTHING; ELSE DELETE FROM public.staff_assignments WHERE user_id=_user_id AND responsibility=_responsibility; END IF; END $$;
CREATE OR REPLACE FUNCTION public.can_access_conversation(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=_id AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.orders o JOIN public.disputes d ON d.order_id=o.id WHERE o.listing_id=c.listing_id AND o.buyer_id=c.buyer_id AND o.seller_id=c.seller_id AND public.can_supervise_dispute(auth.uid(),o.id)) OR ((c.buyer_id=auth.uid() OR c.seller_id=auth.uid()) AND public.same_community(c.buyer_id,c.seller_id)))); $$;
ALTER POLICY disputes_staff_read ON public.disputes USING(public.has_staff(auth.uid(),'disputes') AND public.can_supervise_dispute(auth.uid(),order_id));
CREATE OR REPLACE FUNCTION public.staff_disputes() RETURNS TABLE(id uuid,order_id uuid,opened_by uuid,reason text,status text,resolution text,created_at timestamptz,orders jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_staff(auth.uid(),'disputes')) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; RETURN QUERY SELECT d.id,d.order_id,d.opened_by,d.reason,d.status,d.resolution,d.created_at,jsonb_build_object('amount',o.amount,'buyer_id',o.buyer_id,'seller_id',o.seller_id,'status',o.status,'country',public.account_country(o.seller_id)) FROM public.disputes d JOIN public.orders o ON o.id=d.order_id WHERE public.can_supervise_dispute(auth.uid(),o.id) ORDER BY d.created_at DESC; END $$;
CREATE OR REPLACE FUNCTION public.admin_dispute_conversation(_order_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o record; cid uuid; BEGIN IF NOT public.can_supervise_dispute(auth.uid(),_order_id) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF NOT EXISTS(SELECT 1 FROM public.disputes WHERE order_id=_order_id) THEN RAISE EXCEPTION 'DISPUTE_NOT_FOUND'; END IF; SELECT * INTO o FROM public.orders WHERE id=_order_id; SELECT id INTO cid FROM public.conversations WHERE listing_id=o.listing_id AND buyer_id=o.buyer_id AND seller_id=o.seller_id LIMIT 1; IF cid IS NULL THEN INSERT INTO public.conversations(listing_id,buyer_id,seller_id) VALUES(o.listing_id,o.buyer_id,o.seller_id) RETURNING id INTO cid; END IF; RETURN cid; END $$;
CREATE OR REPLACE FUNCTION public.resolve_staff_dispute(_order_id uuid,_refund boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders%ROWTYPE; BEGIN IF NOT public.can_supervise_dispute(auth.uid(),_order_id) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; SELECT * INTO o FROM public.orders WHERE id=_order_id FOR UPDATE; IF NOT FOUND OR o.status<>'disputed' OR NOT EXISTS(SELECT 1 FROM public.disputes WHERE order_id=o.id AND status='open') THEN RAISE EXCEPTION 'OPEN_DISPUTE_REQUIRED'; END IF; UPDATE public.wallets SET held=held-o.amount,balance=balance+CASE WHEN _refund THEN o.amount ELSE 0 END,updated_at=now() WHERE user_id=o.buyer_id AND held>=o.amount; IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_ESCROW'; END IF; IF _refund THEN INSERT INTO public.wallet_transactions(user_id,type,amount,reference) VALUES(o.buyer_id,'escrow_refund',o.amount,o.id::text); UPDATE public.orders SET status='refunded',updated_at=now() WHERE id=o.id; UPDATE public.listings SET status='active' WHERE id=o.listing_id; ELSE UPDATE public.wallets SET balance=balance+o.amount-o.fee,updated_at=now() WHERE user_id=o.seller_id; IF NOT FOUND THEN RAISE EXCEPTION 'SELLER_WALLET_MISSING'; END IF; INSERT INTO public.wallet_transactions(user_id,type,amount,reference) VALUES(o.seller_id,'escrow_release',o.amount-o.fee,o.id::text),(o.seller_id,'fee',-o.fee,o.id::text); UPDATE public.orders SET status='completed',updated_at=now() WHERE id=o.id; UPDATE public.profiles SET sales_count=sales_count+1 WHERE id=o.seller_id; END IF; UPDATE public.disputes SET status='resolved',resolution=CASE WHEN _refund THEN 'استرجاع المبلغ للمشتري' ELSE 'تحرير المبلغ للبائع' END WHERE order_id=o.id AND status='open'; END $$;